-- Coffer initial schema (docs/CONTRACTS.md §6, verbatim).
--
-- Runs as the owner role inside a single transaction under the migration advisory
-- lock. The role and grant block is executed in that same transaction by the
-- migration runner (internal/store/grants.sql), so a failure part way through
-- leaves no partial schema and no grants against tables that do not exist.
--
-- Do not edit this file once it has been applied anywhere: the runner records its
-- checksum and refuses to start when it changes. Schema changes go in a new
-- numbered file.

CREATE TABLE organizations (
  id           text PRIMARY KEY,
  slug         text NOT NULL UNIQUE,
  created_at   timestamptz NOT NULL DEFAULT now(),
  disabled_at  timestamptz
);

CREATE TABLE users (
  id                   text PRIMARY KEY,
  org_id               text REFERENCES organizations(id),   -- NULL only for the platform admin
  email                text NOT NULL UNIQUE,                -- lowercased
  password_hash        text NOT NULL,
  role                 text NOT NULL,                       -- owner|admin|member|platform_admin
  must_change_password boolean NOT NULL DEFAULT false,
  removed_at           timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE personal_access_tokens (
  id         text PRIMARY KEY,
  user_id    text NOT NULL REFERENCES users(id),
  token_hash text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz
);
CREATE INDEX ON personal_access_tokens (user_id);

CREATE TABLE projects (
  id         text PRIMARY KEY,
  org_id     text NOT NULL REFERENCES organizations(id),
  slug       text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (org_id, slug)                                     -- per-org only; global would leak
);

CREATE TABLE environments (
  id         text PRIMARY KEY,
  project_id text NOT NULL REFERENCES projects(id),
  slug       text NOT NULL,
  protected  boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (project_id, slug)
);

CREATE TABLE project_grants (
  project_id text NOT NULL REFERENCES projects(id),
  user_id    text NOT NULL REFERENCES users(id),
  level      text NOT NULL,                                 -- viewer|reader|writer
  PRIMARY KEY (project_id, user_id)
);

CREATE TABLE service_tokens (
  id         text PRIMARY KEY,
  org_id     text NOT NULL REFERENCES organizations(id),
  project_id text NOT NULL REFERENCES projects(id),
  env_id     text NOT NULL REFERENCES environments(id),
  access     text NOT NULL,                                 -- read|read-write
  name       text,
  token_hash text NOT NULL UNIQUE,
  created_by text NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz
);
CREATE INDEX ON service_tokens (project_id, env_id);

CREATE TABLE project_data_keys (
  project_id  text PRIMARY KEY REFERENCES projects(id),
  wrapped_key bytea NOT NULL,
  nonce       bytea NOT NULL,
  key_version integer NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE secrets (
  id              text PRIMARY KEY,
  env_id          text NOT NULL REFERENCES environments(id),
  key             text NOT NULL,
  current_version bigint NOT NULL DEFAULT 0,                -- the allocator; never MAX()+1
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  updated_by      text,
  UNIQUE (env_id, key)
);

CREATE TABLE secret_versions (
  secret_id  text NOT NULL REFERENCES secrets(id),
  version    bigint NOT NULL,
  ciphertext bytea,                                         -- NULL on a tombstone
  nonce      bytea,
  deleted    boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text,
  PRIMARY KEY (secret_id, version)
);

CREATE TABLE change_requests (
  id             text PRIMARY KEY,
  org_id         text NOT NULL REFERENCES organizations(id),
  project_id     text NOT NULL REFERENCES projects(id),
  env_id         text NOT NULL REFERENCES environments(id),
  secret_id      text REFERENCES secrets(id),               -- NULL for a create-by-set
  key            text NOT NULL,
  op             text NOT NULL,                             -- set|delete|rollback
  payload_ct     bytea,                                     -- AAD-bound to id
  payload_nonce  bytea,
  base_version   bigint NOT NULL,                           -- version seen at proposal time
  target_version bigint,                                    -- rollback source, else NULL
  status         text NOT NULL DEFAULT 'pending',           -- pending|approved|rejected|stale
  proposer_id    text NOT NULL REFERENCES users(id),
  created_at     timestamptz NOT NULL DEFAULT now(),
  resolved_at    timestamptz,
  resolver_id    text REFERENCES users(id)
);
CREATE INDEX ON change_requests (org_id, status);

CREATE TABLE audit_events (
  scope      text NOT NULL,
  seq        bigint NOT NULL,
  ts         timestamptz NOT NULL,
  actor_id   text NOT NULL,
  actor_kind text NOT NULL,
  org_id     text NOT NULL DEFAULT '',
  action     text NOT NULL,
  target     text NOT NULL DEFAULT '',
  source_ip  text NOT NULL DEFAULT '',
  result     text NOT NULL,
  prev_hash  text NOT NULL,
  hash       text NOT NULL,
  PRIMARY KEY (scope, seq)
);

CREATE TABLE audit_heads (
  scope text PRIMARY KEY,
  seq   bigint NOT NULL,
  hash  text NOT NULL
);

-- schema_migrations is NOT created here. The migration runner owns it and creates it
-- before applying anything, because it must record the row for the very migration that
-- would otherwise create the table — creating it here is circular and made every boot
-- fail with 42P07 after the first rollback. The runner's definition keeps exactly this
-- column set (version, applied_at, checksum).

-- Append-only enforcement.
--
-- A superuser's tamper succeeds on purpose: restore.sh must be able to reproduce a
-- tampered dump so that `coffer audit verify` can report it, and the hash chain is
-- what detects the tamper, not the trigger. For every non-superuser role, including
-- coffer_app, UPDATE and DELETE raise.
CREATE OR REPLACE FUNCTION audit_events_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF (SELECT rolsuper FROM pg_roles WHERE rolname = current_user) THEN
    RETURN COALESCE(NEW, OLD);   -- superuser tamper succeeds so verify can report it
  END IF;
  RAISE EXCEPTION 'audit_events is append-only';
END $$;

CREATE TRIGGER audit_events_no_update BEFORE UPDATE OR DELETE ON audit_events
  FOR EACH ROW EXECUTE FUNCTION audit_events_append_only();
CREATE TRIGGER audit_events_no_truncate BEFORE TRUNCATE ON audit_events
  FOR EACH STATEMENT EXECUTE FUNCTION audit_events_append_only();
